# Marks of 10 students
marks = [95, 82, 78, 65, 45, 90, 88, 72, 55, 60]

grades = []   # new list to store grades

for m in marks:
    if m >= 90:
        grades.append('A')
    elif m >= 80:
        grades.append('B')
    elif m >= 70:
        grades.append('C')
    elif m >= 60:
        grades.append('D')
    else:
        grades.append('F')

print('Marks:', marks)
print('Grades:', grades)

