% Given feed data
m_in = 100;
xH2O_feed = 0.60;

% Top and bottom compositions
xH2O_top = 0.20; xEth_top = 0.35; xMeth_top = 0.45;
xH2O_bot = 0.65; xEth_bot = 0.25; xMeth_bot = 0.10;

% Set up equations:
% (1) m_top + m_bottom = m_in
% (2) xH2O_top*m_top + xH2O_bot*m_bottom = xH2O_feed*m_in

Amat = [1 1; xH2O_top xH2O_bot];
bvec = [m_in; xH2O_feed*m_in];

sol = Amat\bvec;   % solve linear system
m_top = sol(1);
m_bottom = sol(2);

fprintf('Mass flow into system = %d\n', m_in)
fprintf('Mass flow out of top = %f\n', m_top)
fprintf('Mass flow out of bottom = %f\n', m_bottom)

% Now solve for x (ethanol fraction in feed) using ethanol balance
% xEth_feed*m_in = xEth_top*m_top + xEth_bot*m_bottom
xEth_feed = (xEth_top*m_top + xEth_bot*m_bottom)/m_in;
fprintf('Ethanol fraction in feed (x) = %f\n', xEth_feed)

