% Given data
V = [1 2 3 4 5 6 7 8 9];
RPM = [520 1050 1560 2100 2610 3140 3650 4190 4630];

% (i) Plot experimental data points
figure;
plot(V, RPM, 'ko', 'MarkerFaceColor', 'k')
hold on;

% (ii) Linear model fit RPM = aV + b
p_linear = polyfit(V, RPM, 1);
fprintf('Linear model: a = %f, b = %f\n', p_linear(1), p_linear(2))

% (iii) Quadratic model fit RPM = aV^2 + bV + c
p_quad = polyfit(V, RPM, 2);
fprintf('Quadratic model: a = %f, b = %f, c = %f\n', p_quad(1), p_quad(2), p_quad(3))

% (iv) Plot both fitted curves with the data
V_fit = linspace(1, 9, 100);
RPM_linear = polyval(p_linear, V_fit);
RPM_quad = polyval(p_quad, V_fit);

plot(V_fit, RPM_linear, 'b-', 'LineWidth', 1.5)
plot(V_fit, RPM_quad, 'r--', 'LineWidth', 1.5)
hold off;

xlabel('Voltage (V)')
ylabel('Speed (RPM)')
title('Voltage vs RPM with Linear and Quadratic Fit')
legend('Experimental Data', 'Linear Fit', 'Quadratic Fit', 'Location', 'northwest')
grid on;

